export interface ConnectorConfig {
  stripeSecretKey: string
  fetch?: typeof fetch
}

export interface HubSpotContactPayload {
  properties: {
    email: string
    firstname: string
    lastname: string
    lifecyclestage: string
  }
}

export interface StripeCustomerResponse {
  id: string
  object: string
  email: string
  name: string
  created: number
  livemode: boolean
}

export interface HandleResult {
  stripeCustomerId: string
  stripeCustomer: StripeCustomerResponse
}

export async function handle(
  payload: HubSpotContactPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.properties) {
    throw new Error('Missing required field: properties')
  }
  const { email, firstname, lastname, lifecyclestage } = payload.properties

  if (!email) {
    throw new Error('Missing required field: properties.email')
  }
  if (!firstname) {
    throw new Error('Missing required field: properties.firstname')
  }
  if (!lastname) {
    throw new Error('Missing required field: properties.lastname')
  }
  if (lifecyclestage !== 'customer') {
    throw new Error(`Invalid lifecyclestage: expected 'customer', got '${lifecyclestage}'`)
  }

  const fullName = `${firstname} ${lastname}`.trim()

  const response = await fetchImpl('https://api.stripe.com/v1/customers', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.stripeSecretKey}`,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: new URLSearchParams({
      email,
      name: fullName,
    }).toString(),
  })

  if (!response.ok) {
    throw new Error(`Stripe API error: ${response.status} ${response.statusText} at POST https://api.stripe.com/v1/customers`)
  }

  const customer = (await response.json()) as StripeCustomerResponse

  return {
    stripeCustomerId: customer.id,
    stripeCustomer: customer,
  }
}

